      "content": "{\n  \"name\": \"@agentscope-ai/reme-dsh-plugin\",\n  \"version\": \"0.1.3\",\n  \"description\": \"ReMe memory and context integration for DeepSeek Harness\",\n  \"type\": \"module\",\n  \"main\": \"./dist/index.js\",\n  \"types\": \"./dist/index.d.ts\",\n  \"exports\": {\n    \".\": {\n      \"types\": \"./dist/index.d.ts\",\n      \"import\": \"./dist/index.js\"\n    },\n    \"./client\": {\n      \"default\": \"./dist/client.js\"\n    },\n    \"./package.json\": \"./package.json\"\n  },\n  \"files\": [\n    \"dist\",\n    \"cordis.patch.yml\",\n    \"README.md\",\n    \"README_ZH.md\",\n    \"figures\"\n  ],\n  \"dsh\": {\n    \"client\": {\n      \"inject\": [\n        \"@deepseek-ai/dsh-client-locale\",\n        \"@deepseek-ai/dsh-client-connection\",\n        \"@deepseek-ai/dsh-client-ui-settings\",\n        \"@deepseek-ai/dsh-client-ui-settings-plugins\",\n        \"@deepseek-ai/dsh-client-ui-plugin-manager\",\n        \"@deepseek-ai/dsh-client-ui-primitives\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"build\": \"npm run clean && tsc -p tsconfig.json && node scripts/build-client.mjs\",\n    \"clean\": \"node -e \\\"require('node:fs').rmSync('dist', { force: true, recursive: true })\\\"\",\n    \"format\": \"prettier --write .\",\n    \"format:check\": \"prettier --check .\",\n    \"lint\": \"eslint .\",\n    \"pretest\": \"npm run build\",\n    \"test\": \"node --test tests/*.test.mjs\",\n    \"test:package\": \"node scripts/test-package.mjs\",\n    \"prepare\": \"npm run build\",\n    \"typecheck\": \"tsc -p tsconfig.json --noEmit\"\n  },\n  \"peerDependencies\": {\n    \"@deepseek-ai/cordis\": \"~4.0.4 || ^4.0.5-alpha.1\",\n    \"@deepseek-ai/dsh-client-ui-primitives\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/dsh-llm\": \"^0.1.7-rc.2 || ^0.2.0-rc.2 || ^0.2.1-alpha.2\",\n    \"@deepseek-ai/dsh-tools\": \"^0.1.